package com.playflow.controller;

import com.playflow.dto.ApiDtos.*;
import com.playflow.entity.Entities.*;
import com.playflow.entity.Entities;
import com.playflow.repository.*;
import com.playflow.service.AuthService;
import com.playflow.service.PaymentService;
import com.playflow.service.PaymentRecoveryService;
import com.playflow.service.ReconciliationService;
import org.springframework.http.HttpStatus;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.transaction.annotation.Transactional;
import jakarta.validation.Valid;
import java.math.BigDecimal;
import java.time.*;
import java.util.*;
import java.util.stream.Collectors;

@RestController @RequestMapping("/api")
public class ApiController {
    private final AuthService auth; private final UserRepository users; private final WalletRepository wallets; private final PaymentRepository payments; private final JourneyRepository journeys; private final NotificationRepository notifications; private final com.playflow.repository.SpendingLimitRepository spendingLimits; private final PaymentService paymentService; private final PaymentRecoveryService recovery; private final ReconciliationService reconciliation;
    public ApiController(AuthService auth,UserRepository users,WalletRepository wallets,PaymentRepository payments,JourneyRepository journeys,NotificationRepository notifications,com.playflow.repository.SpendingLimitRepository spendingLimits,PaymentService paymentService,PaymentRecoveryService recovery,ReconciliationService reconciliation){this.auth=auth;this.users=users;this.wallets=wallets;this.payments=payments;this.journeys=journeys;this.notifications=notifications;this.spendingLimits=spendingLimits;this.paymentService=paymentService;this.recovery=recovery;this.reconciliation=reconciliation;}
    @PostMapping("/auth/register") public AuthResponse register(@Valid @RequestBody RegisterRequest body){return auth.register(body);}
    @PostMapping("/auth/login") public AuthResponse login(@Valid @RequestBody LoginRequest body){return auth.login(body);}
    @GetMapping("/users/me") public UserView me(@AuthenticationPrincipal String email){return user(email);}
    @GetMapping("/users/me/spending-limits") public SpendingLimitView spendingLimits(@AuthenticationPrincipal String email){return spendingLimitView(spendingLimits.findById(current(email).id).orElseThrow());}
    @PutMapping("/users/me/spending-limits") public SpendingLimitView updateSpendingLimits(@AuthenticationPrincipal String email,@Valid @RequestBody SpendingLimitRequest body){SpendingLimit limit=spendingLimits.findById(current(email).id).orElseThrow();if(body.monthlyLimit().compareTo(body.dailyLimit())<0)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Monthly limit must be at least the daily limit");limit.dailyLimit=body.dailyLimit();limit.monthlyLimit=body.monthlyLimit();limit.updatedAt=java.time.Instant.now();return spendingLimitView(spendingLimits.save(limit));}
    @PutMapping("/users/me") public UserView update(@AuthenticationPrincipal String email,@RequestBody ProfileRequest body){User u=current(email);if(body.name()==null||body.name().isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Name is required");u.name=body.name().trim();users.save(u);return userView(u);}
    @Transactional
    @GetMapping("/users/lookup") public RecipientView lookup(@AuthenticationPrincipal String email,@RequestParam(required=false) String query,@RequestParam(name="emailToFind",required=false) String legacyQuery,@RequestParam(required=false) String contactName){User self=current(email);String value=query!=null?query:legacyQuery;if(value==null||value.isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Enter a phone number");String phone=value.trim().replaceAll("\\D","");if(phone.startsWith("91")&&phone.length()==12)phone=phone.substring(2);if(phone.length()!=10)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Enter a 10-digit phone number");final String normalizedPhone=phone;User found=users.findByPhoneNumber(normalizedPhone).orElseGet(()->createDemoRecipient(normalizedPhone,contactName));if(self.id.equals(found.id))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"You cannot transfer money to yourself");return new RecipientView(found.id,found.name,found.phoneNumber==null?null:"••••••"+found.phoneNumber.substring(Math.max(0,found.phoneNumber.length()-4)));}
    private User createDemoRecipient(String phone,String contactName){String name=contactName==null||contactName.isBlank()?"Demo recipient · "+phone.substring(6):contactName.trim();if(name.length()>120)name=name.substring(0,120);User recipient=new User(name,"recipient+"+phone+"@payflow.demo","!DEMO_RECIPIENT_ONLY!",phone);recipient.kycStatus="DEMO";recipient=users.save(recipient);wallets.save(new Wallet(recipient.id));spendingLimits.save(new SpendingLimit(recipient.id,new BigDecimal("5000.00"),new BigDecimal("50000.00")));return recipient;}
    @GetMapping("/wallet/{userId}") public WalletView wallet(@AuthenticationPrincipal String email,@PathVariable Long userId){User u=current(email);if(!u.id.equals(userId))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"You can only view your own wallet");Wallet w=wallets.findByUserId(userId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Wallet not found"));return new WalletView(w.userId,w.balance,w.currency);}
    @PostMapping("/wallet/deposit") public WalletView deposit(@AuthenticationPrincipal String email,@Valid @RequestBody AmountRequest body){return paymentService.changeBalance(current(email).id,body.amount(),true);}
    @PostMapping("/wallet/withdraw") public WalletView withdraw(@AuthenticationPrincipal String email,@Valid @RequestBody AmountRequest body){return paymentService.changeBalance(current(email).id,body.amount(),false);}
    @PostMapping("/payments") public PaymentView transfer(@AuthenticationPrincipal String email,@RequestHeader("Idempotency-Key") String key,@Valid @RequestBody TransferRequest body){return paymentService.transfer(current(email).id,body,key);}
    @GetMapping("/payments/user/{userId}") public List<PaymentView> transactions(@AuthenticationPrincipal String email,@PathVariable Long userId){if(!current(email).id.equals(userId))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"You can only view your own transactions");return paymentService.transactions(userId);}
    @GetMapping("/payments/{transactionId}") public PaymentView payment(@AuthenticationPrincipal String email,@PathVariable String transactionId){User u=current(email);return paymentService.view(paymentService.get(transactionId,u.id));}
    @GetMapping("/transactions/{transactionId}/events") public List<JourneyView> journey(@AuthenticationPrincipal String email,@PathVariable String transactionId){return paymentService.journey(transactionId,current(email).id);}
    @GetMapping("/transactions/{transactionId}/recovery") public RecoveryView recovery(@AuthenticationPrincipal String email,@PathVariable String transactionId){return recovery.assess(transactionId,current(email).id);}
    @GetMapping("/notifications") public List<NotificationView> notifications(@AuthenticationPrincipal String email){return notifications.findByUserIdOrderByCreatedAtDesc(current(email).id).stream().map(n->new NotificationView(n.id,n.message,n.transactionId,n.createdAt,n.read)).toList();}
    @PutMapping("/notifications/{notificationId}/read") public NotificationView markNotificationRead(@AuthenticationPrincipal String email,@PathVariable Long notificationId){AppNotification n=notifications.findById(notificationId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Notification not found"));if(!n.userId.equals(current(email).id))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Notification not found");n.read=true;notifications.save(n);return new NotificationView(n.id,n.message,n.transactionId,n.createdAt,n.read);}
    @PutMapping("/notifications/read-all") public Map<String,Integer> markAllNotificationsRead(@AuthenticationPrincipal String email){List<AppNotification> unread=notifications.findByUserIdOrderByCreatedAtDesc(current(email).id).stream().filter(n->!n.read).toList();unread.forEach(n->n.read=true);notifications.saveAll(unread);return Map.of("updated",unread.size());}
    @GetMapping("/admin/users") public List<UserView> adminUsers(){return users.findAll().stream().map(this::userView).toList();}
    @PutMapping("/admin/users/{userId}/role") public UserView updateUserRole(@AuthenticationPrincipal String email,@PathVariable Long userId,@RequestParam String role){String next=role.toUpperCase(Locale.ROOT);if(!Set.of("USER","ADMIN").contains(next))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Role must be USER or ADMIN");User u=users.findById(userId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"User not found"));if("ADMIN".equals(u.role)&&"USER".equals(next)&&(u.email.equalsIgnoreCase(email)||users.countByRole("ADMIN")<=1))throw new ResponseStatusException(HttpStatus.CONFLICT,"Keep at least one other administrator active");u.role=next;return userView(users.save(u));}
    @GetMapping("/admin/payments") public List<PaymentView> adminPayments(){return payments.findAll().stream().sorted(Comparator.comparing((Payment p)->p.createdAt).reversed()).limit(200).map(paymentService::view).toList();}
    @GetMapping("/admin/reconciliation") public ReconciliationReport reconciliation(){return reconciliation.reconcile();}
    @GetMapping("/dashboard") public DashboardView dashboard(@AuthenticationPrincipal String email){
        Long id=current(email).id; List<PaymentView> all=paymentService.transactions(id); LocalDate today=LocalDate.now(); YearMonth currentMonth=YearMonth.from(today);
        List<Payment> outgoing=payments.findBySenderIdOrReceiverIdOrderByCreatedAtDesc(id,id).stream().filter(p->p.senderId.equals(id)&&p.status.equals("SUCCESS")&&!p.category.equals("Wallet")).toList();
        BigDecimal spent=outgoing.stream().filter(p->YearMonth.from(p.createdAt.atZone(ZoneId.systemDefault())).equals(currentMonth)).map(p->p.amount).reduce(BigDecimal.ZERO,BigDecimal::add);
        List<TrendPoint> trend=new ArrayList<>();
        for(int i=5;i>=0;i--){YearMonth month=currentMonth.minusMonths(i);BigDecimal total=outgoing.stream().filter(p->YearMonth.from(p.createdAt.atZone(ZoneId.systemDefault())).equals(month)).map(p->p.amount).reduce(BigDecimal.ZERO,BigDecimal::add);trend.add(new TrendPoint(month.getMonth().name().substring(0,3),total));}
        Wallet w=wallets.findByUserId(id).orElseThrow();
        return new DashboardView(new WalletView(id,w.balance,w.currency),all.size(),all.stream().filter(p->p.status().equals("SUCCESS")).count(),all.stream().filter(p->p.status().equals("FAILED")).count(),all.stream().filter(p->Set.of("PENDING","PROCESSING").contains(p.status())).count(),all.stream().limit(8).toList(),spent,trend);
    }
    @GetMapping({"/insights/summary", "/local-insights/summary"}) public InsightSummary insights(@AuthenticationPrincipal String email,@RequestParam(defaultValue="month") String period){String p=period.toLowerCase(Locale.ROOT);if(!Set.of("day","month","year").contains(p))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Period must be day, month, or year");Long id=current(email).id;LocalDate today=LocalDate.now();List<Payment> outgoing=payments.findBySenderIdOrReceiverIdOrderByCreatedAtDesc(id,id).stream().filter(t->t.senderId.equals(id)&&t.status.equals("SUCCESS")&&!t.category.equals("Wallet")&&inPeriod(t.createdAt,p,today)).toList();Map<String,BigDecimal> categories=outgoing.stream().collect(Collectors.groupingBy(t->t.category,TreeMap::new,Collectors.reducing(BigDecimal.ZERO,t->t.amount,BigDecimal::add)));BigDecimal total=outgoing.stream().map(pmt->pmt.amount).reduce(BigDecimal.ZERO,BigDecimal::add);String top=categories.entrySet().stream().max(Map.Entry.comparingByValue()).map(Map.Entry::getKey).orElse("no category yet");String label=switch(p){case "day"->"today";case "year"->"this year";default->"this month";};LocalDate previousDate=switch(p){case "day"->today.minusDays(1);case "year"->today.minusYears(1);default->today.minusMonths(1);};BigDecimal previous=payments.findBySenderIdOrReceiverIdOrderByCreatedAtDesc(id,id).stream().filter(t->t.senderId.equals(id)&&t.status.equals("SUCCESS")&&!t.category.equals("Wallet")&&inPeriod(t.createdAt,p,previousDate)).map(t->t.amount).reduce(BigDecimal.ZERO,BigDecimal::add);String suggestion;if(total.signum()==0)suggestion="No outgoing payments recorded "+label+" yet.";else if(previous.signum()>0){BigDecimal delta=total.subtract(previous).multiply(BigDecimal.valueOf(100)).divide(previous,0,java.math.RoundingMode.HALF_UP);suggestion="You've spent ₹"+total.toPlainString()+" "+label+". Most went to "+top+"; that's "+delta.abs()+"% "+(delta.signum()>=0?"more":"less")+" than the previous period.";}else suggestion="You've spent ₹"+total.toPlainString()+" "+label+". Most of it went to "+top+".";return new InsightSummary(p,total,categories,outgoing.stream().limit(30).map(paymentService::view).toList(),suggestion);}
    @GetMapping("/insights/categories") public Map<String,BigDecimal> categories(@AuthenticationPrincipal String email,@RequestParam(defaultValue="month") String period){return insights(email,period).categoryTotals();}
    private boolean inPeriod(Instant at,String p,LocalDate today){LocalDate d=at.atZone(ZoneId.systemDefault()).toLocalDate();return switch(p){case "day"->d.equals(today);case "year"->d.getYear()==today.getYear();default->d.getYear()==today.getYear()&&d.getMonth()==today.getMonth();};}
    private SpendingLimitView spendingLimitView(SpendingLimit limit){return new SpendingLimitView(limit.userId,limit.dailyLimit,limit.monthlyLimit,limit.updatedAt);}
    private User current(String email){return users.findByEmailIgnoreCase(email).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"User not found"));}
    private UserView user(String email){return userView(current(email));} private UserView userView(User u){return new UserView(u.id,u.name,u.email,u.role,u.kycStatus,u.phoneNumber);}
}
